322	/**
323	 * Posts a comment on a live issue. Mentions written as `@handle` in the body
324	 * are resolved against the org's members here, so the stored row and the
325	 * `comment.created` payload agree on who was mentioned — the notification
326	 * fan-out reads that list rather than re-parsing the markdown.
327	 */
328	export async function createComment(
329	  actor: Actor,
330	  input: CreateCommentInput,
331	): Promise<Comment> {
332	  assertOrgScope(actor, input.orgId);
333	
334	  const issue = requireFound(
335	    await issueRepo.findIssueById(input.orgId, input.issueId),
336	    "Issue",
337	    input.issueId,
338	  );
339	  assertCan(actor, "comment:create", issueResource(issue));
340	  assertNotArchived("Issue", issue.id, issue);
341	
342	  const verdict = await consumeRateLimit(input.orgId, COMMENT_CREATE_BUCKET);
343	  if (!verdict.allowed) {
344	    throw new Error(
345	      `Comment rate limit reached; try again after ${verdict.resetAt}`,
346	    );
347	  }
348	
349	  const mentionedUserIds = await resolveMentionedUsers(
350	    input.orgId,
351	    input.body,
352	    input.mentionedUserIds,
353	  );
354	
355	  const comment = await commentRepo.insertComment(
356	    { ...input, mentionedUserIds: [...mentionedUserIds] },
357	    actor.userId,
358	  );
359	
360	  await emit("comment.created", {
361	    ...actorEnvelope(actor),
362	    commentId: comment.id,
363	    issueId: comment.issueId,
364	    mentionedUserIds,
365	  });
