1016	): Promise<void> {
1017	  const endpoints = await webhookRepo.listEndpoints(orgId);
1018	
1019	  for (const endpoint of endpoints) {
1020	    if (!endpoint.enabled) continue;
1021	
1022	    const wanted: readonly string[] = JSON.parse(endpoint.eventTypes) as string[];
1023	    if (!wanted.includes(eventType)) continue;
1024	
1025	    await webhookRepo.enqueueDelivery(orgId, endpoint.id, eventType, payload);
1026	  }
1027	}
