1035	    orgId: actor.orgId,
1036	    userId: actor.userId,
1037	    plan,
1038	    role: actor.role,
1039	    overrides,
1040	  };
1041	}
1042	/**
1043	 * Server-side flag context construction and the org-level override toggle.
1044	 *
1045	 * Must call (do not reimplement): assertCan, isEnabled, snapshotFlags, emit
1046	 */
1047	import { emit } from "@/lib/event-bus";
1048	import { isEnabled, snapshotFlags } from "@/lib/feature-flags";
1049	import { assertCan } from "@/lib/permissions";
1050	import { getFlagDefinition } from "@/config/feature-flags";
1051	import * as orgRepo from "@/server/repositories/organization-repository";
1052	import { actorEnvelope, orgResource, requireFound } from "./_support";
1053	import type { ToggleFeatureFlagInput } from "@/schemas/feature-flag";
