1063	export function buildFlagContext(
1064	  actor: Actor | null,
1065	  org: Organization | null,
1066	): FlagContext {
1067	  return {
1068	    orgId: org?.id ?? actor?.orgId ?? null,
1069	    userId: actor?.userId ?? null,
