324	/** Groups a feed page by calendar day, newest day first. */
325	export function groupByDay(
326	  events: readonly ActivityEvent[],
327	): readonly ActivityGroup[] {
328	  const byDay = new Map<string, ActivityEvent[]>();
329	
330	  for (const event of events) {
331	    const day = event.occurredAt.slice(0, 10);
332	    const bucket = byDay.get(day) ?? [];
333	    bucket.push(event);
334	    byDay.set(day, bucket);
