536	      used: usage.seatsUsed,
537	    });
538	  }
539	
540	  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
541	    await emit("billing.limit_exceeded", {
542	      orgId,
543	      actorId: null,
544	      occurredAt: toIsoTimestamp(new Date()),
545	      resource: "projects",
546	      limit: limits.projects,
547	      used: usage.projectsUsed,
548	    });
549	  }
