613	export async function buildDigest(
614	  orgId: OrgId,
615	  recipientId: UserId,
616	  windowStart: IsoTimestamp,
617	  windowEnd: IsoTimestamp,
618	): Promise<DigestBundle | null> {
619	  const org = await orgRepo.findOrgById(orgId);
620	  if (!org) return null;
