817	    const expiring = await subscriptionRepo.listTrialsEndingBefore(stamp);
818	    const freeLimits = getPlanLimits(FALLBACK_PLAN);
819	
820	    for (const subscription of expiring) {
821	      const orgId = subscription.orgId as OrgId;
822	      const usage = await usageRepo.getUsage(orgId);
823	
824	      if (
825	        usage.seatsUsed > freeLimits.seats ||
826	        usage.projectsUsed > freeLimits.projects
827	      ) {
828	        result.failed += 1;
829	        logger.warn("trial expired but tenant is over the free plan", {
830	          orgId,
831	          seats: usage.seatsUsed,
832	          projects: usage.projectsUsed,
833	        });
834	        continue;
835	      }
836	
837	      await subscriptionRepo.updateSubscriptionPlan(
838	        orgId,
839	        FALLBACK_PLAN,
840	        subscription.interval,
841	      );
842	
843	      await emit("billing.plan_changed", {
844	        orgId,
845	        actorId: null,
846	        occurredAt: stamp,
847	        from: subscription.plan,
848	        to: FALLBACK_PLAN,
849	      });
850	
851	      result.processed += 1;
852	    }
853	  });
854	}
855	/**
856	 * Scans for issues past `dueAt` and emits `issue.overdue`, which the notification fan-out turns into alerts.
857	 *
858	 * Must call (do not reimplement): emit, shouldFilterArchived
859	 */
860	import { emit } from "@/lib/event-bus";
861	import { createLogger } from "@/lib/logger";
862	import { shouldFilterArchived } from "@/lib/soft-delete";
863	import * as issueRepo from "@/server/repositories/issue-repository";
864	import * as usageRepo from "@/server/repositories/usage-repository";
865	import { toIsoTimestamp } from "@/types/common";
866	import { runJob } from "./types";
867	import type { JobResult } from "@/server/jobs/types";
868	
869	/** How many organizations one pass sweeps. */
870	const ORG_BATCH = 50;
871	
872	/** Archived issues are never overdue — an archived issue has no due date. */
873	const LIVE_ONLY = {} as const;
874	
875	const logger = createLogger("overdue-issue-job");
876	
877	/**
878	 * Issues already announced this process's lifetime. A later sweep still
879	 * finds a still-open, still-overdue issue — this is what keeps the job from
880	 * re-emitting `issue.overdue` for it on every pass.
881	 */
882	const reported = new Set<string>();
883	
884	/** Test-only: clears the reported set so a fresh scenario starts empty. */
885	export function resetOverdueTracking(): void {
886	  reported.clear();
887	}
888	
889	/**
890	 * Publishes one `issue.overdue` per still-open, past-due issue. The job owns
891	 * no notification logic: it announces the fact, and whoever cares (in-app
892	 * alerts, the digest, webhooks) reacts on the bus.
893	 */
894	export async function runOverdueIssueJob(now: Date): Promise<JobResult> {
895	  return runJob("overdue-issues", async (result) => {
896	    if (!shouldFilterArchived(LIVE_ONLY)) {
897	      logger.warn("archive scope misconfigured; skipping sweep", {});
898	      return;
899	    }
900	
901	    const stamp = toIsoTimestamp(now);
902	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
903	
904	    for (const orgId of orgIds) {
905	      const overdue = await issueRepo.listOverdueIssues(orgId, stamp);
906	
907	      for (const issue of overdue) {
908	        if (issue.dueAt === null) continue;
909	        if (reported.has(issue.id)) continue;
910	
911	        try {
912	          await emit("issue.overdue", {
913	            orgId,
914	            actorId: null,
915	            occurredAt: stamp,
916	            issueId: issue.id,
917	            projectId: issue.projectId,
918	            dueAt: issue.dueAt,
919	            assigneeId: issue.assigneeId,
920	          });
921	          reported.add(issue.id);
922	          result.processed += 1;
923	        } catch (error) {
924	          result.failed += 1;
925	          logger.error("failed to announce overdue issue", {
926	            issueId: issue.id,
927	            reason: error instanceof Error ? error.message : String(error),
928	          });
929	        }
930	      }
931	    }
932	  });
933	}
934	/**
935	 * Drains pending webhook deliveries with exponential backoff; disabled unless the org's plan includes webhooks.
936	 *
937	 * Must call (do not reimplement): isEnabled, getPlanLimits, signPayload
938	 */
939	import { getPlanLimits } from "@/config/plan-limits";
940	import { isEnabled } from "@/lib/feature-flags";
941	import { createLogger } from "@/lib/logger";
942	import * as orgRepo from "@/server/repositories/organization-repository";
943	import * as webhookRepo from "@/server/repositories/webhook-repository";
944	import { buildFlagContext } from "@/server/services/feature-flag-service";
945	import { signPayload } from "@/server/services/webhook-service";
946	import { toIsoTimestamp } from "@/types/common";
947	import { runJob } from "./types";
948	import type { JobResult } from "@/server/jobs/types";
949	import type { OrgId } from "@/types/common";
950	
951	/** How many deliveries one pass claims. */
952	const CLAIM_BATCH = 25;
953	
954	/** Attempts after which a delivery is marked failed for good. */
955	const MAX_ATTEMPTS = 6;
956	
957	const logger = createLogger("webhook-delivery-job");
958	
959	/**
960	 * Delivers each claimed row. There is no outbound HTTP in Taskflow — the
961	 * corpus builds and runs offline — so "delivery" means computing the
962	 * signature the receiver would verify and logging the attempt. The retry
963	 * bookkeeping around it is the part that has to be right.
964	 */
965	export async function runWebhookDeliveryJob(now: Date): Promise<JobResult> {
966	  return runJob("webhook-delivery", async (result) => {
967	    const claimed = await webhookRepo.claimPendingDeliveries(CLAIM_BATCH);
968	
969	    for (const delivery of claimed) {
970	      const orgId = delivery.orgId as OrgId;
971	
972	      if (!(await orgAllowsWebhooks(orgId))) {
973	        await webhookRepo.markDeliveryFailed(
974	          orgId,
975	          delivery.id,
976	          "webhooks are not included in this organization's plan",
977	        );
978	        result.failed += 1;
979	        continue;
980	      }
981	
982	      if (delivery.attempts > MAX_ATTEMPTS) {
983	        await webhookRepo.markDeliveryFailed(
984	          orgId,
985	          delivery.id,
986	          `giving up after ${delivery.attempts} attempts`,
987	        );
988	        result.failed += 1;
989	        continue;
990	      }
991	
992	      const endpoint = (await webhookRepo.listEndpoints(orgId)).find(
993	        (row) => row.id === delivery.endpointId,
994	      );
995	
996	      if (!endpoint || !endpoint.enabled) {
997	        await webhookRepo.markDeliveryFailed(
998	          orgId,
999	          delivery.id,
1000	          "endpoint is missing or disabled",
1001	        );
1002	        result.failed += 1;
1003	        continue;
1004	      }
1005	
1006	      const signature = signPayload(endpoint.secret, delivery.payload);
1007	
1008	      logger.info("webhook delivered", {
1009	        deliveryId: delivery.id,
1010	        endpoint: endpoint.url,
1011	        eventType: delivery.eventType,
1012	        signature: signature.slice(0, 16),
1013	        backoffMs: backoffMs(delivery.attempts),
1014	      });
1015	
1016	      await webhookRepo.markDelivered(orgId, delivery.id, toIsoTimestamp(now));
1017	      result.processed += 1;
1018	    }
1019	  });
1020	}
1021	
1022	/** 1s, 2s, 4s … capped at five minutes; attempt 0 retries immediately. */
1023	export function backoffMs(attempts: number): number {
1024	  if (attempts <= 0) return 0;
1025	  return Math.min(300_000, 2 ** (attempts - 1) * 1_000);
1026	}
1027	
1028	async function orgAllowsWebhooks(orgId: OrgId): Promise<boolean> {
1029	  const org = await orgRepo.findOrgById(orgId);
1030	  if (!org) return false;
1031	
1032	  if (getPlanLimits(org.plan).webhooks <= 0) return false;
1033	  return isEnabled("webhooks", buildFlagContext(null, org));
1034	}
1035	/**
1036	 * Permanently removes rows archived longer ago than the plan's `retentionDays`.
1037	 *
1038	 * Must call (do not reimplement): getPlanLimits, isArchived
1039	 */
1040	import { getPlanLimits } from "@/config/plan-limits";
1041	import { createLogger } from "@/lib/logger";
1042	import { isArchived } from "@/lib/soft-delete";
1043	import * as activityRepo from "@/server/repositories/activity-repository";
1044	import * as issueRepo from "@/server/repositories/issue-repository";
1045	import * as orgRepo from "@/server/repositories/organization-repository";
1046	import * as searchRepo from "@/server/repositories/search-repository";
1047	import * as usageRepo from "@/server/repositories/usage-repository";
1048	import { toIsoTimestamp } from "@/types/common";
1049	import { runJob } from "./types";
1050	import type { JobResult } from "@/server/jobs/types";
1051	
1052	const ORG_BATCH = 25;
1053	const PAGE_SIZE = 100;
1054	const MS_PER_DAY = 24 * 60 * 60 * 1000;
1055	
1056	const logger = createLogger("cleanup-archived-job");
1057	
1058	/**
1059	 * The retention sweep. Soft-deleted rows are kept for as long as the plan
1060	 * promises and no longer: the cut-off comes from `retentionDays`, so an
1061	 * enterprise tenant keeps years of history where a free one keeps a month.
1062	 *
1063	 * Only the search documents are actually dropped here — the issue rows stay,
1064	 * because the audit log still points at them — while the audit rows past the
1065	 * window are purged outright.
1066	 */
1067	export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
1068	  return runJob("cleanup-archived", async (result) => {
1069	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
1070	
1071	    for (const orgId of orgIds) {
1072	      const org = await orgRepo.findOrgById(orgId);
1073	      if (!org) continue;
1074	
1075	      const { retentionDays } = getPlanLimits(org.plan);
1076	      const cutoff = toIsoTimestamp(
1077	        new Date(now.getTime() - retentionDays * MS_PER_DAY),
1078	      );
1079	
1080	      const archived = await issueRepo.listIssues({
1081	        orgId,
1082	        limit: PAGE_SIZE,
1083	        cursor: null,
1084	        includeArchived: true,
1085	      });
1086	
1087	      for (const issue of archived.items) {
1088	        if (!isArchived(issue)) continue;
1089	        if (issue.archivedAt === null || issue.archivedAt > cutoff) continue;
1090	
1091	        await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
1092	        result.processed += 1;
1093	      }
1094	
1095	      try {
1096	        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
1097	        result.processed += purged;
1098	      } catch (error) {
1099	        result.failed += 1;
1100	        logger.error("activity purge failed", {
1101	          orgId,
1102	          reason: error instanceof Error ? error.message : String(error),
1103	        });
1104	      }
1105	    }
1106	  });
1107	}
