/**
 * The read-only lock: a workspace whose subscription is not in good standing
 * refuses every member write until billing is sorted out.
 *
 * This module is the pure half — the rule and the error. The stored
 * subscription is looked up by `assertWorkspaceWritable()` in
 * `@/server/services/billing-service`.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

/** Thrown by a write into a workspace that is locked. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`This workspace is read-only: ${describeLockReason(reason)}`);
    this.name = "WorkspaceLockedError";
  }
}

/** Human wording for a lock reason, shared by the error and the banner. */
export function describeLockReason(reason: WorkspaceLockReason): string {
  switch (reason) {
    case "past_due":
      return "its subscription payment is past due";
    case "canceled":
      return "its subscription has been canceled";
    case "trial_ended":
      return "its trial has ended";
  }
}

/**
 * Why the workspace is locked at `now`, or `null` when it is writable.
 *
 * - no subscription, or `active`: writable;
 * - `past_due`: locked;
 * - `trialing`: locked once the period end is reached (at or after it);
 * - `canceled`: locked once the cancellation date is reached; a cancellation
 *   scheduled for later leaves the workspace writable until then, and one
 *   with no date at all counts as canceled already.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null || subscription === undefined) return null;

  const at = now.getTime();

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return at >= new Date(subscription.currentPeriodEnd).getTime()
        ? "trial_ended"
        : null;
    case "canceled": {
      if (subscription.cancelAt === null || subscription.cancelAt === undefined) {
        return "canceled";
      }
      const cancelAt = new Date(subscription.cancelAt).getTime();
      // An unreadable date cannot postpone the cancellation.
      return Number.isNaN(cancelAt) || at >= cancelAt ? "canceled" : null;
    }
    default:
      return null;
  }
}
EOF
