/**
 * The read-only lock: a workspace whose subscription is not in good standing
 * refuses member writes, while reads, billing and background work carry on.
 */
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { WorkspaceLockedError, lockReasonFor } from "@/lib/billing-lock";
import { isDomainError, toAppError } from "@/lib/errors";
import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { getDb, subscriptions } from "@/server/db";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as billingService from "@/server/services/billing-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import * as notificationService from "@/server/services/notification-service";
import * as organizationService from "@/server/services/organization-service";
import * as projectService from "@/server/services/project-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Subscription, SubscriptionStatus } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

const NOW = new Date("2026-06-01T12:00:00.000Z");
const EARLIER = "2026-05-31T12:00:00.000Z" as IsoTimestamp;
const LATER = "2026-06-02T12:00:00.000Z" as IsoTimestamp;

function subscription(overrides: Partial<Subscription>): Subscription {
  return {
    id: "sub" as Subscription["id"],
    orgId: "org" as OrgId,
    plan: "growth",
    interval: "monthly",
    status: "active",
    seats: 1,
    currentPeriodStart: EARLIER,
    currentPeriodEnd: LATER,
    cancelAt: null,
    createdAt: EARLIER,
    updatedAt: EARLIER,
    ...overrides,
  };
}

describe("lockReasonFor", () => {
  it("leaves a missing or active subscription writable", () => {
    expect(lockReasonFor(null, NOW)).toBeNull();
    expect(lockReasonFor(subscription({ status: "active" }), NOW)).toBeNull();
    expect(
      lockReasonFor(subscription({ status: "active", cancelAt: EARLIER }), NOW),
    ).toBeNull();
  });

  it("locks a past-due subscription", () => {
    expect(lockReasonFor(subscription({ status: "past_due" }), NOW)).toBe("past_due");
  });

  it("locks a trial from the instant its period ends", () => {
    const at = toIsoTimestamp(NOW);
    expect(
      lockReasonFor(subscription({ status: "trialing", currentPeriodEnd: LATER }), NOW),
    ).toBeNull();
    expect(
      lockReasonFor(subscription({ status: "trialing", currentPeriodEnd: at }), NOW),
    ).toBe("trial_ended");
    expect(
      lockReasonFor(subscription({ status: "trialing", currentPeriodEnd: EARLIER }), NOW),
    ).toBe("trial_ended");
  });

  it("locks a cancellation once its date is reached, or at once without one", () => {
    const at = toIsoTimestamp(NOW);
    expect(
      lockReasonFor(subscription({ status: "canceled", cancelAt: LATER }), NOW),
    ).toBeNull();
    expect(
      lockReasonFor(subscription({ status: "canceled", cancelAt: at }), NOW),
    ).toBe("canceled");
    expect(
      lockReasonFor(subscription({ status: "canceled", cancelAt: null }), NOW),
    ).toBe("canceled");
  });
});

describe("error mapping", () => {
  it("maps the lock to plan_limit_exceeded with the reason in meta", () => {
    const error = new WorkspaceLockedError("org" as OrgId, "past_due");
    expect(error.code).toBe("plan_limit_exceeded");
    expect(isDomainError(error)).toBe(true);

    const shape = toAppError(error);
    expect(shape.code).toBe("plan_limit_exceeded");
    expect(shape.meta?.reason).toBe("past_due");
  });
});

describe("a locked workspace", () => {
  let cleanup: () => void;
  let tenant: Tenant;

  function setStatus(
    status: SubscriptionStatus,
    patch: { cancelAt?: string | null; currentPeriodEnd?: string } = {},
  ): void {
    getDb()
      .update(subscriptions)
      .set({ status, ...patch })
      .where(eq(subscriptions.orgId, tenant.org.id))
      .run();
  }

  beforeAll(async () => {
    cleanup = await useTemporaryDatabase();
    tenant = await createTenant("locked", "growth");
    await usageRepo.recomputeUsage(tenant.org.id);
  });

  beforeEach(() => {
    setStatus("active", { cancelAt: null });
  });

  afterAll(() => {
    cleanup();
  });

  it("refuses an issue write, stores nothing and publishes nothing", async () => {
    setStatus("past_due");
    const seen: string[] = [];
    const off = subscribe("issue.created", (payload) => {
      seen.push(payload.issueId);
    });
    const before = await issueRepo.countIssues(tenant.org.id, tenant.project.id);

    const attempt = issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id),
    );
    await expect(attempt).rejects.toBeInstanceOf(WorkspaceLockedError);
    await expect(attempt).rejects.toMatchObject({
      orgId: tenant.org.id,
      reason: "past_due",
    });
    off();

    expect(seen).toEqual([]);
    await expect(
      issueRepo.countIssues(tenant.org.id, tenant.project.id),
    ).resolves.toBe(before);
  });

  it("still gives a caller without permission the permission refusal", async () => {
    setStatus("past_due");
    await expect(
      issueService.createIssue(
        tenant.actors.viewer,
        issueInput(tenant.org.id, tenant.project.id),
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("keeps reads, billing and notification housekeeping working", async () => {
    setStatus("past_due");

    await expect(
      projectService.listProjects(tenant.actors.viewer, {
        orgId: tenant.org.id,
        limit: 10,
        cursor: null,
      }),
    ).resolves.toBeDefined();

    const billing = await billingService.getBillingSummary(
      tenant.actors.owner,
      tenant.org.id,
    );
    expect(billing.lockReason).toBe("past_due");

    const summary = await organizationService.getOrganizationSummary(
      tenant.actors.member,
      tenant.org.id,
    );
    expect(summary.lockReason).toBe("past_due");

    await expect(
      notificationService.markAllRead(tenant.actors.member, tenant.org.id),
    ).resolves.toBe(0);
    await expect(
      billingService.updateSeats(tenant.actors.owner, {
        orgId: tenant.org.id,
        seats: 5,
      }),
    ).resolves.toMatchObject({ seats: 5 });
  });

  it("keeps a pending invitation pending when it is accepted while locked", async () => {
    const token = "a-token-for-the-locked-workspace";
    const invitation = await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "late@locked.test",
        role: "member",
        expiresInDays: 14,
      },
      tenant.userIds.owner,
      hashToken(token),
    );
    const user = await userRepo.insertUser({
      email: "late@locked.test",
      name: "Late",
      passwordHash: "seed",
    });

    setStatus("canceled", { cancelAt: null });

    await expect(
      invitationService.acceptInvitation(user.id, { token }),
    ).rejects.toMatchObject({ reason: "canceled" });
    await expect(
      invitationService.acceptInvitation(user.id, { token: "no-such-token" }),
    ).rejects.not.toBeInstanceOf(WorkspaceLockedError);

    await expect(memberRepo.findMember(tenant.org.id, user.id)).resolves.toBeNull();
    const pending = await invitationRepo.listPendingInvitations(tenant.org.id);
    expect(pending.map((row) => row.id)).toContain(invitation.id);
  });

  it("is writable again after a plan change", async () => {
    setStatus("past_due");
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id),
    ).rejects.toBeInstanceOf(WorkspaceLockedError);

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "monthly",
    });

    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id),
    ).resolves.toBeUndefined();
    await expect(
      issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id),
      ),
    ).resolves.toMatchObject({ orgId: tenant.org.id });
  });

  it("evaluates the lock at the given instant", async () => {
    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    const end = new Date(subscription!.currentPeriodEnd);
    setStatus("trialing");

    await expect(
      billingService.assertWorkspaceWritable(
        tenant.org.id,
        new Date(end.getTime() - 1),
      ),
    ).resolves.toBeUndefined();
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id, end),
    ).rejects.toMatchObject({ reason: "trial_ended" });
  });

  it("leaves an ended trial that outgrew the free plan locked", async () => {
    setStatus("trialing", { currentPeriodEnd: EARLIER });

    // Four seats do not fit the free plan's three, so the job declines.
    await runTrialExpiryJob(new Date());

    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id),
    ).rejects.toMatchObject({ reason: "trial_ended" });
  });
});
EOF
